sliderInit:
jQuery(function($){

							var widget_layers_widget_slide_4_slider = $('#layers-widget-slide-4').swiper({
							mode:'horizontal'
							,onInit: function(s){
								$(document).trigger( 'layers-slider-init', s);
							}
							,bulletClass: 'swiper-pagination-switch'
							,bulletActiveClass: 'swiper-active-switch swiper-visible-switch'
							,paginationClickable: true
							,watchActiveIndex: true
																							,pagination: '.widget-layers-widget-slide-4-pages'
																									,loop: true
																								, autoplay: 10000																							});

															widget_layers_widget_slide_4_slider.enableKeyboardControl();


							$('#layers-widget-slide-4').find('.arrows a').on( 'click', function(e){
								e.preventDefault();

								$that = $(this);

								if( $that.hasClass( 'swiper-pagination-switch' ) ){
									widget_layers_widget_slide_4_slider.slideTo( $that.index() );
								} else if( $that.hasClass( 'l-left-arrow' ) ){
									widget_layers_widget_slide_4_slider.slidePrev();
								} else if( $that.hasClass( 'l-right-arrow' ) ){
									widget_layers_widget_slide_4_slider.slideNext();
								}

								return false;
							});

							widget_layers_widget_slide_4_slider.init();
							if ( ! $('#layers-widget-slide-4').prev('.widget').length ) {
								if ( ! $('#layers-widget-slide-4').hasClass( '.full-screen' ) ) {
									jQuery('.header-site.header-overlay').css( 'transition', '0s' );
									setTimeout( function(){ jQuery('.header-site.header-overlay').css( 'transition', '' ); }, 1000 );
									jQuery('body').addClass( 'header-overlay-no-push' );
								}
							}

							$( '#layers-widget-slide-4' ).removeClass('loading').addClass('loaded');
						});
